/**
 * Walks every organization that has not been deleted, `batchSize` ids at a
 * time, in id order. Keyset paging on `id` means a sweep sees every live org
 * however many there are, and a page boundary holds even if an org is
 * archived while the sweep is running.
 */
export async function* iterateLiveOrgIds(
  batchSize: number,
): AsyncGenerator<OrgId> {
  const size = Math.max(1, batchSize);
  let after: string | null = null;

  for (;;) {
    const rows = getDb()
      .select({ id: organizations.id })
      .from(organizations)
      .where(
        and(
          isNull(organizations.archivedAt),
          after === null ? undefined : gt(organizations.id, after),
        ),
      )
      .orderBy(asc(organizations.id))
      .limit(size)
      .all();

    for (const row of rows) yield brandId<OrgId>(row.id);

    if (rows.length < size) return;
    after = rows[rows.length - 1].id;
  }
}

